from flask import Flask, redirect, url_for

app = Flask(__name__)

@app.route("/new")
def new_route():
    return "This is the new route"

@app.route("/old")
def old_route():
    return redirect(url_for('new_route'))

if __name__ == '__main__':
    app.run(debug=True)
